function MIN_PROOF_LEN(T, a, b):
    if a == b: return 0                      # empty derivation (reflexivity)
    dist <- map {a: 0}; Q <- queue([a])
    while Q not empty:
        x <- dequeue(Q)
        for each y with (x -> y) in T:        # apply one axiom
            if y not in dist:
                dist[y] <- dist[x] + 1
                if y == b: return dist[y]      # first reach = shortest proof
                enqueue(Q, y)
    return None                                # b unreachable: a !|- b

