function BARRIER_CERTIFY(T, a, b):
    S <- LEAST_CLOSED_SET(T, a)        # forward closure from {a}
    if b in S:
        return ('DERIVABLE', S)         # no barrier exists
    else:
        return ('NOT_DERIVABLE', S)     # S is a closed cut: a in S, b not in S

function LEAST_CLOSED_SET(T, a):
    S <- {a}; Q <- queue([a])
    while Q not empty:
        x <- dequeue(Q)
        for each y with (x -> y) in T:
            if y not in S: add y to S; enqueue(Q, y)
    return S

