    seen: Set[Atom] = {source}; q: deque[Atom] = deque([source])
    while q:
        x = q.popleft()
        for y in adj.get(x, []):
            if y not in seen:
                seen.add(y); q.append(y)
    return len(seen)

def main() -> None:
    n, trials = 600, 12
    rng = random.Random(1)
    cs = [i / 20 for i in range(1, 61)]
    fracs: List[float] = []
    for c in cs:
        acc = sum(conclusion_size(random_theory(n, c, rng), 0) / n
